def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            # End of line
            fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Potential end of quoted field or escaped quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Escaped quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i == len(line):
                            fields.append(field)
                            return fields
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            if i == len(line):
                                fields.append("")
                            break
                        else:
                            # Invalid: closing quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Invalid: unquoted field contains quote
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line):
                # Consume comma
                i += 1
                if i == len(line):
                    fields.append("")

    return fields

